mapper.select:
SELECT ts.staff_id AS sfvhStaffId, ts.staff_phone AS staffPhone, ts.staff_name AS staffName, ts.staff_group_id AS staffGroupId, tv.vehi_id AS vehiId, tv.vehi_no AS vehiNo, tv.vehi_nickname AS vehiNickname , tv.vehi_plate_no AS vehiPlateNo FROM T_STAFF ts LEFT JOIN T_STAFF_VEHI tsv ON ts.staff_id =tsv.sfvh_staff_id LEFT JOIN T_VEHI tv ON tsv.sfvh_vehi_no = tv.vehi_no AND ts.`staff_airport_code`=tv.`vehi_airport_code` WHERE ts.staff_airport_code = #{staffAirportCode}
AND ts.staff_aptarea_code=#{staffAptareaCode}
AND ts.staff_type >=3 ORDER BY ts.staff_level

SELECT vehi_id AS vehiId, vehi_no AS vehiNo, vehi_nickname AS vehiNickname, vehi_type AS vehiType, vehi_brand AS vehiBrand, vehi_availability AS vehiAvailability, vehi_fuel_figu AS vehiFuelFigu, vehi_company AS vehiCompany, vehi_serv_station AS vehiServStation, vehi_airport_code AS vehiAirportCode, vehi_aptarea_code AS vehiAptareaCode, vehi_plate_no AS vehiPlateNo, vehi_fuel_code AS vehiFuelCode, vehi_fuel_sno AS vehiFuelSno, remark AS remark FROM T_VEHI WHERE 1 = 1
AND vehi_airport_code =#{staffAirportCode}
AND vehi_aptarea_code=#{staffAptareaCode}

SELECT staff_id AS staffId, staff_pwd AS staffPwd, staff_name AS staffName, staff_age AS staffAge, staff_gender AS staffGender, staff_type AS staffType, staff_phone AS staffPhone, staff_company AS staffCompany, staff_serv_station AS staffServStation, staff_airport_code AS staffAirportCode, staff_aptarea_code AS staffAptareaCode, staff_group_id AS staffGroupId, print_server_url AS printServerUrl FROM T_STAFF WHERE 1 = 1
AND staff_airport_code=#{staffAirportCode}
AND staff_aptarea_code=#{staffAptareaCode}
ORDER BY staff_name DESC

SELECT COUNT(staff_name)
FROM T_STAFF
WHERE staff_name = #{staffName}
